const MISSING = { status: 'rejected', code: 'not_found', reason: 'not in the Chain scene' };

/** The id a per-input route is keyed by in KEYED. */
const inputIdOf = (route, input) => {
  const value = input ?? {};
  switch (route) {
    case 'lines/page': return `${value.key?.sessionId}:${value.section}`;
    case 'lines/read': return value.key?.sessionId;
    case 'goals/read': return value.goalId;
    case 'goals/display': case 'tasks/query': return value.goalRef?.goalId;
    case 'executions/read': return value.runId;
    case 'executions/history': case 'executions/brief': return value.runRef?.runId;
    case 'verification/round': return value.roundRef !== undefined ? `round:${value.roundRef.roundId}` : `run:${value.subjectRunRef?.runId}`;
    case 'controls/read': return value.intentId;
    default: return undefined;
  }
};

export const scene = {
  now: "2026-10-23T09:00:01.000Z",
  reply(route, input) {
    if (route in KEYED) return KEYED[route][inputIdOf(route, input)] ?? MISSING;
    return ROUTES[route];
  },
};
